set -euo pipefail
mkdir -p /opt/brigada-core-src
find /opt/brigada-core-src -mindepth 1 -maxdepth 1 ! -name gradlew ! -name gradle ! -name .gradle -exec rm -rf -- {} +
printf '%s' '' | base64 -d | tar -xzf - -C /opt/brigada-core-src
cd /opt/brigada-core-src
chmod +x gradlew
./gradlew --no-daemon clean build
printf '\nARTIFACTS\n'
find build/libs -maxdepth 1 -type f -printf '%f %s bytes\n'
sha256sum build/libs/*.jar
